-- Hallenverzeichnis Deutschschweiz – Seed (SPEC-053)
-- Stand: 29.10.2026, 88 Hallen. Recherche aus offiziellen Hallen-Websites, VSBK-Mitgliederliste
-- (kletteranlagen.ch), kletterportal.ch, Tourismus- und Gemeindeseiten; Koordinaten aus dem amtlichen
-- Gebäudeadressverzeichnis (swisstopo, api3.geo.admin.ch). Unabhängige Zweitprüfung je Halle (pruef_status).
-- Keine Logos/Fotos, keine Personennamen. Öffnungszeiten/Preise = Momentaufnahme, ändern sich.
-- Voraussetzung: Migration 20261029_spec053_hallen_verzeichnis.sql ist eingespielt.
-- Wiederholbar: bestehende Zeilen (gleicher Name + PLZ) werden aktualisiert, gym_id/ausgeblendet bleiben unberührt.

BEGIN;

ON CONFLICT ((lower(name)), plz) DO UPDATE SET
  adresse = EXCLUDED.adresse, ort = EXCLUDED.ort, kanton = EXCLUDED.kanton, land = EXCLUDED.land, lat = EXCLUDED.lat, lng = EXCLUDED.lng, website = EXCLUDED.website, art = EXCLUDED.art, telefon = EXCLUDED.telefon, email = EXCLUDED.email, betreiber_typ = EXCLUDED.betreiber_typ, oeffnungszeiten = EXCLUDED.oeffnungszeiten, preise = EXCLUDED.preise, quelle_urls = EXCLUDED.quelle_urls, pruef_status = EXCLUDED.pruef_status, geprueft_am = EXCLUDED.geprueft_am, notiz = EXCLUDED.notiz;

COMMIT;

